'use client'

import Image from 'next/image'
import { useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { ArrowRight, MapPin } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ShowcaseLocation = {
  id: string
  name: string
  description?: string
  image: { src: string; alt: string }
  href?: string
}

export type LocationShowcaseProps = {
  title: string
  description?: string
  locations: ShowcaseLocation[]
  action?: { label: string; href: string }
  linkLabel?: string
  className?: string
}

export function LocationShowcase({
  title,
  description,
  locations,
  action,
  linkLabel = 'Saiba mais',
  className,
}: LocationShowcaseProps) {
  const [activeId, setActiveId] = useState(locations[0]?.id)
  const reduceMotion = useReducedMotion()
  const active = locations.find((location) => location.id === activeId) ?? locations[0]

  if (!active) return null

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container grid gap-10 lg:grid-cols-[0.9fr_1.1fr] lg:items-center">
        <div>
          <h2 className="text-3xl font-bold uppercase tracking-tight md:text-5xl">{title}</h2>
          {description ? (
            <p className="mt-5 max-w-lg text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
          <ul className="mt-8 grid gap-1 sm:grid-cols-2" role="tablist" aria-label={title}>
            {locations.map((location) => {
              const selected = location.id === active.id
              return (
                <li key={location.id}>
                  <button
                    type="button"
                    role="tab"
                    aria-selected={selected}
                    onClick={() => setActiveId(location.id)}
                    onMouseEnter={() => setActiveId(location.id)}
                    onFocus={() => setActiveId(location.id)}
                    className={cn(
                      'flex w-full items-center gap-2 rounded-xl px-4 py-3 text-left text-sm font-semibold transition',
                      selected ? 'bg-primary text-primary-foreground shadow-lg' : 'hover:bg-muted',
                    )}
                  >
                    <MapPin className="h-4 w-4 shrink-0" aria-hidden="true" />
                    {location.name}
                  </button>
                </li>
              )
            })}
          </ul>
          {action ? (
            <a
              href={action.href}
              className="group mt-8 inline-flex items-center gap-2 font-semibold text-primary"
            >
              {action.label}
              <ArrowRight className="h-4 w-4 transition group-hover:translate-x-1" />
            </a>
          ) : null}
        </div>

        <div
          className="relative aspect-[4/3] overflow-hidden rounded-3xl bg-muted shadow-xl"
          role="tabpanel"
        >
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.div
              key={active.id}
              initial={reduceMotion ? false : { opacity: 0, scale: 1.08 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={reduceMotion ? undefined : { opacity: 0 }}
              transition={{ duration: 0.6 }}
              className="absolute inset-0"
            >
              <Image
                src={active.image.src}
                alt={active.image.alt}
                fill
                className="object-cover"
                sizes="(min-width: 1024px) 55vw, 100vw"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/75 via-black/10 to-transparent" />
              <div className="absolute inset-x-0 bottom-0 p-6 text-white md:p-8">
                <h3 className="text-2xl font-bold">{active.name}</h3>
                {active.description ? (
                  <p className="mt-2 max-w-md text-sm leading-6 text-white/80">
                    {active.description}
                  </p>
                ) : null}
                {active.href ? (
                  <a
                    href={active.href}
                    className="mt-4 inline-flex rounded-full bg-white px-4 py-2 text-sm font-semibold text-black transition hover:bg-primary hover:text-primary-foreground"
                  >
                    {linkLabel}
                  </a>
                ) : null}
              </div>
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
    </section>
  )
}

import type { CSSProperties } from 'react'
import { ArrowUpRight, MapPin } from 'lucide-react'
import { cn } from '@/lib/utils'

export type MapEmbedSectionProps = {
  /** Endereço ou termo usado no Google Maps. */
  query: string
  title?: string
  description?: string
  eyebrow?: string
  address?: string
  directionsHref?: string
  directionsLabel?: string
  height?: number
  className?: string
}

export function MapEmbedSection({
  query,
  title,
  description,
  eyebrow,
  address,
  directionsHref,
  directionsLabel = 'Como chegar',
  height = 450,
  className,
}: MapEmbedSectionProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'map-title' : undefined}
    >
      <div className="container">
        {title ? (
          <div className="mb-10 max-w-2xl">
            {eyebrow ? (
              <p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">
                {eyebrow}
              </p>
            ) : null}
            <h2
              id="map-title"
              className={cn('text-3xl font-bold tracking-tight md:text-4xl', eyebrow && 'mt-3')}
            >
              {title}
            </h2>
            {description ? <p className="mt-4 text-muted-foreground">{description}</p> : null}
          </div>
        ) : null}
        <div className="overflow-hidden rounded-3xl border bg-muted shadow-sm">
          <iframe
            title={`Mapa: ${query}`}
            src={`https://www.google.com/maps?q=${encodeURIComponent(query)}&output=embed`}
            className="block h-80 w-full border-0 md:h-[var(--map-height)]"
            style={{ '--map-height': `${height}px` } as CSSProperties}
            loading="lazy"
            referrerPolicy="no-referrer-when-downgrade"
            allowFullScreen
          />
          {address ? (
            <div className="flex flex-col gap-3 border-t bg-card px-5 py-4 sm:flex-row sm:items-center sm:justify-between md:px-6">
              <p className="flex items-start gap-2 text-sm font-medium">
                <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-primary" aria-hidden="true" />
                {address}
              </p>
              {directionsHref ? (
                <a
                  href={directionsHref}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex shrink-0 items-center gap-1 text-sm font-semibold text-primary hover:underline"
                >
                  {directionsLabel}
                  <ArrowUpRight className="h-4 w-4" aria-hidden="true" />
                  <span className="sr-only">(abre em nova aba)</span>
                </a>
              ) : null}
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

export type StatsGridProps = {
  title?: string
  description?: string
  stats: Array<{ value: string; label: string; detail?: string }>
  columns?: 2 | 3 | 4
  className?: string
}

export function StatsGrid({ title, description, stats, columns = 4, className }: StatsGridProps) {
  const columnClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'stats-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="stats-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        {description ? <p className="mt-3 max-w-2xl text-muted-foreground">{description}</p> : null}
        <dl
          className={cn(
            'mt-10 grid gap-px overflow-hidden rounded-2xl border bg-border',
            columnClass,
          )}
        >
          {stats.map((stat) => (
            <div key={`${stat.value}-${stat.label}`} className="bg-background p-7">
              <dt className="text-sm text-muted-foreground">{stat.label}</dt>
              <dd className="mt-2 text-4xl font-bold tracking-tight text-primary">{stat.value}</dd>
              {stat.detail ? (
                <p className="mt-2 text-sm text-muted-foreground">{stat.detail}</p>
              ) : null}
            </div>
          ))}
        </dl>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { useMemo, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { ArrowUpRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type FilterableCard = {
  id: string
  title: string
  description?: string
  category: string
  image?: { src: string; alt: string }
  href?: string
  badge?: string
}

export type FilterableCardGridProps = {
  title?: string
  description?: string
  items: FilterableCard[]
  allLabel?: string
  columns?: 2 | 3 | 4
  className?: string
}

export function FilterableCardGrid({
  title,
  description,
  items,
  allLabel = 'Todos',
  columns = 3,
  className,
}: FilterableCardGridProps) {
  const [category, setCategory] = useState('all')
  const reduceMotion = useReducedMotion()
  const categories = useMemo(() => Array.from(new Set(items.map((item) => item.category))), [items])
  const filtered = category === 'all' ? items : items.filter((item) => item.category === category)
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-2xl">
            {title ? (
              <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{title}</h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
            ) : null}
          </div>
          <div
            className="flex max-w-full gap-2 overflow-x-auto pb-1"
            role="group"
            aria-label="Filtrar cards"
          >
            {[
              { value: 'all', label: allLabel },
              ...categories.map((item) => ({ value: item, label: item })),
            ].map((filter) => (
              <button
                type="button"
                key={filter.value}
                onClick={() => setCategory(filter.value)}
                aria-pressed={category === filter.value}
                className={cn(
                  'shrink-0 rounded-full border px-4 py-2 text-sm font-medium transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                  category === filter.value
                    ? 'border-foreground bg-foreground text-background'
                    : 'bg-background hover:border-primary/40 hover:text-primary',
                )}
              >
                {filter.label}
              </button>
            ))}
          </div>
        </div>

        <motion.div layout className={cn('mt-10 grid gap-5', columnsClass)}>
          <AnimatePresence mode="popLayout">
            {filtered.map((item) => (
              <motion.article
                layout
                key={item.id}
                initial={reduceMotion ? false : { opacity: 0, scale: 0.96 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduceMotion ? undefined : { opacity: 0, scale: 0.96 }}
                transition={{ duration: reduceMotion ? 0 : 0.25 }}
                className="group min-w-0 overflow-hidden rounded-2xl border bg-card shadow-sm transition-shadow hover:shadow-xl"
              >
                {item.image ? (
                  <div className="relative aspect-[4/3] overflow-hidden bg-muted">
                    <Image
                      src={item.image.src}
                      alt={item.image.alt}
                      fill
                      className="object-cover transition duration-500 group-hover:scale-105"
                      sizes="(min-width: 1024px) 33vw, 50vw"
                    />
                    {item.badge ? (
                      <span className="absolute left-3 top-3 rounded-full bg-background/85 px-3 py-1 text-xs font-semibold backdrop-blur">
                        {item.badge}
                      </span>
                    ) : null}
                  </div>
                ) : null}
                <div className="p-5">
                  <p className="text-xs font-bold uppercase tracking-wider text-primary">
                    {item.category}
                  </p>
                  <h3 className="mt-2 text-lg font-semibold">{item.title}</h3>
                  {item.description ? (
                    <p className="mt-2 line-clamp-2 text-sm leading-6 text-muted-foreground">
                      {item.description}
                    </p>
                  ) : null}
                  {item.href ? (
                    <a
                      href={item.href}
                      className="mt-5 inline-flex items-center gap-1.5 text-sm font-semibold text-primary hover:underline"
                    >
                      Explorar <ArrowUpRight className="h-4 w-4" />
                    </a>
                  ) : null}
                </div>
              </motion.article>
            ))}
          </AnimatePresence>
        </motion.div>
      </div>
    </section>
  )
}

'use client'

import { useId, useState } from 'react'
import { ChevronDown } from 'lucide-react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type FAQBorderedItem = {
  question: string
  answer: string
}

export type FAQBorderedProps = {
  items: readonly FAQBorderedItem[]
  title?: string
  eyebrow?: string
  description?: string
  embedded?: boolean
  defaultOpenIndex?: number | null
  tone?: AccentTone
  className?: string
}

const answerBackgrounds: Record<AccentTone, string> = {
  glow: 'bg-[#121212]',
  industrial: 'bg-slate-50',
  'industrial-dark': 'bg-slate-950',
}

/** FAQ em bloco contornado com perguntas sobre fundo de painel e respostas expansíveis. */
export function FAQBordered({
  items,
  title,
  eyebrow = 'FAQ',
  description,
  embedded = false,
  defaultOpenIndex = 0,
  tone = 'glow',
  className,
}: FAQBorderedProps) {
  const t = getAccentTone(tone)
  const baseId = useId()
  const [active, setActive] = useState<number | null>(defaultOpenIndex)

  const list = (
    <div className={cn('divide-y border', t.divide, t.border, tone === 'glow' && 'rounded-md')}>
      {items.map((item, index) => {
        const isOpen = active === index
        const panelId = `${baseId}-${index}`
        return (
          <div key={item.question}>
            <h3>
              <button
                type="button"
                onClick={() => setActive(isOpen ? null : index)}
                className={cn(
                  'flex w-full items-center justify-between gap-4 px-5 py-5 text-left transition-colors sm:px-7',
                  t.panel,
                  t.panelHover,
                  t.focus,
                )}
                aria-expanded={isOpen}
                aria-controls={panelId}
              >
                <span className={cn('text-sm font-semibold tracking-wide sm:text-base', t.strong)}>
                  {item.question}
                </span>
                <ChevronDown
                  className={cn(
                    'h-5 w-5 shrink-0 transition-transform duration-300',
                    t.accent,
                    isOpen && 'rotate-180',
                  )}
                  aria-hidden
                />
              </button>
            </h3>
            <div
              id={panelId}
              role="region"
              className={cn(
                'grid transition-all duration-500 ease-out',
                isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0',
              )}
            >
              <div className="overflow-hidden" aria-hidden={!isOpen}>
                <p
                  className={cn(
                    'px-5 py-5 text-sm leading-relaxed sm:px-7 sm:text-base',
                    answerBackgrounds[tone],
                    t.body,
                  )}
                >
                  {item.answer}
                </p>
              </div>
            </div>
          </div>
        )
      })}
    </div>
  )

  if (embedded) {
    return (
      <div className={className}>
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            titleAs="h2"
            className="mb-6"
          />
        ) : null}
        {list}
      </div>
    )
  }

  return (
    <section className={cn(t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            description={description}
            layout="split"
            className="mb-10 lg:mb-12"
          />
        ) : null}
        {list}
      </div>
    </section>
  )
}

import Image from 'next/image'

import { cn } from '@/lib/utils'

export type AccentTestimonial = {
  name: string
  content: string
  role?: string
  avatar?: string
  rating?: number
}

export function TestimonialAvatar({
  name,
  src,
  className,
}: {
  name: string
  src?: string
  className?: string
}) {
  const initials = name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')

  return (
    <span
      className={cn(
        'relative flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden text-sm font-semibold',
        className,
      )}
    >
      {src ? (
        <Image src={src} alt={name} fill sizes="48px" className="object-cover" />
      ) : (
        <span aria-hidden>{initials}</span>
      )}
    </span>
  )
}

import type { CSSProperties } from 'react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

import { TestimonialAvatar, type AccentTestimonial } from './TestimonialAvatar'

export type TestimonialsColumnsProps = {
  title: string
  testimonials: readonly AccentTestimonial[]
  eyebrow?: string
  description?: string
  columns?: 2 | 3
  duration?: number
  tone?: AccentTone
  className?: string
}

const keyframes =
  '@keyframes accent-testimonials-scroll-y{from{transform:translateY(0)}to{transform:translateY(-50%)}}'

const visibility = ['', 'hidden md:block', 'hidden lg:block']

/** Depoimentos em colunas verticais infinitas com velocidades diferentes e pausa no hover. */
export function TestimonialsColumns({
  title,
  testimonials,
  eyebrow,
  description,
  columns = 3,
  duration = 20,
  tone = 'glow',
  className,
}: TestimonialsColumnsProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const groups = Array.from({ length: columns }, (_, column) =>
    testimonials.filter((_, index) => index % columns === column),
  ).filter((group) => group.length)
  const fade = isGlow
    ? 'from-[#121212]'
    : tone === 'industrial'
      ? 'from-slate-50'
      : 'from-slate-950'

  return (
    <section className={cn('overflow-hidden py-14 lg:py-20', t.section, className)}>
      <style>{keyframes}</style>
      <div className="container">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          align="center"
          className="mb-12"
        />

        <ul className="-mx-4 flex snap-x snap-mandatory gap-4 overflow-x-auto px-4 pb-2 [scrollbar-width:none] md:hidden [&::-webkit-scrollbar]:hidden">
          {testimonials.map((testimonial) => (
            <li key={testimonial.name} className="w-[85%] shrink-0 snap-center">
              <figure
                className={cn(
                  'h-full border p-6 shadow-sm',
                  t.panel,
                  t.border,
                  isGlow ? 'rounded-2xl' : '',
                )}
              >
                <blockquote className={cn('text-sm leading-relaxed', t.body)}>
                  &ldquo;{testimonial.content}&rdquo;
                </blockquote>
                <figcaption className="mt-5 flex items-center gap-3">
                  <TestimonialAvatar
                    name={testimonial.name}
                    src={testimonial.avatar}
                    className={cn(
                      'h-10 w-10',
                      isGlow
                        ? 'rounded-full bg-[#121212] text-[#ffb0eb]'
                        : 'bg-slate-100 text-amber-600',
                    )}
                  />
                  <span>
                    <span className={cn('block text-sm font-semibold', t.strong)}>
                      {testimonial.name}
                    </span>
                    {testimonial.role ? (
                      <span className={cn('block text-xs', t.muted)}>{testimonial.role}</span>
                    ) : null}
                  </span>
                </figcaption>
              </figure>
            </li>
          ))}
        </ul>

        <div className="relative mx-auto hidden max-h-[680px] max-w-6xl gap-6 overflow-hidden md:grid md:grid-cols-2 lg:grid-cols-3">
          {groups.map((group, column) => (
            <div key={column} className={cn('group', visibility[column])}>
              <div
                className="flex flex-col gap-6 [animation:accent-testimonials-scroll-y_var(--marquee-duration)_linear_infinite] group-hover:[animation-play-state:paused] motion-reduce:[animation:none]"
                style={{ '--marquee-duration': `${duration + column * 5}s` } as CSSProperties}
              >
                {[...group, ...group].map((testimonial, index) => (
                  <figure
                    key={`${testimonial.name}-${index}`}
                    aria-hidden={index >= group.length}
                    className={cn(
                      'border p-6 shadow-sm',
                      t.panel,
                      t.border,
                      isGlow ? 'rounded-2xl' : '',
                    )}
                  >
                    <blockquote className={cn('text-sm leading-relaxed', t.body)}>
                      &ldquo;{testimonial.content}&rdquo;
                    </blockquote>
                    <figcaption className="mt-5 flex items-center gap-3">
                      <TestimonialAvatar
                        name={testimonial.name}
                        src={testimonial.avatar}
                        className={cn(
                          'h-10 w-10',
                          isGlow
                            ? 'rounded-full bg-[#121212] text-[#ffb0eb]'
                            : 'bg-slate-100 text-amber-600',
                        )}
                      />
                      <span>
                        <span className={cn('block text-sm font-semibold', t.strong)}>
                          {testimonial.name}
                        </span>
                        {testimonial.role ? (
                          <span className={cn('block text-xs', t.muted)}>{testimonial.role}</span>
                        ) : null}
                      </span>
                    </figcaption>
                  </figure>
                ))}
              </div>
            </div>
          ))}
          <div
            className={cn(
              'pointer-events-none absolute inset-x-0 top-0 h-24 bg-gradient-to-b to-transparent',
              fade,
            )}
            aria-hidden
          />
          <div
            className={cn(
              'pointer-events-none absolute inset-x-0 bottom-0 h-24 bg-gradient-to-t to-transparent',
              fade,
            )}
            aria-hidden
          />
        </div>
      </div>
    </section>
  )
}

'use client'

import { useRef, useState, type FormEvent } from 'react'
import { motion, useReducedMotion } from 'framer-motion'
import { Check, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'

export type QuoteField = {
  name: string
  label: string
  type?: 'text' | 'email' | 'tel' | 'textarea' | 'select'
  options?: string[]
  placeholder?: string
  required?: boolean
  fullWidth?: boolean
}

export type QuoteStep = { title: string; fields: QuoteField[] }

export type MultiStepQuoteFormProps = {
  title?: string
  steps: QuoteStep[]
  onSubmit: (data: Record<string, string>) => Promise<void> | void
  previousLabel?: string
  nextLabel?: string
  submitLabel?: string
  successTitle?: string
  successDescription?: string
  errorMessage?: string
  className?: string
}

const fieldClass =
  'w-full rounded-xl border bg-background px-4 py-3 text-sm transition focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20'

export function MultiStepQuoteForm({
  title,
  steps,
  onSubmit,
  previousLabel = 'Anterior',
  nextLabel = 'Próximo',
  submitLabel = 'Enviar',
  successTitle = 'Recebemos sua solicitação!',
  successDescription = 'Nossa equipe entrará em contato em breve.',
  errorMessage = 'Não foi possível enviar. Tente novamente.',
  className,
}: MultiStepQuoteFormProps) {
  const [step, setStep] = useState(0)
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle')
  const formRef = useRef<HTMLFormElement>(null)
  const reduceMotion = useReducedMotion()
  const isLast = step === steps.length - 1

  function validateStep() {
    const fieldset = formRef.current?.querySelector<HTMLFieldSetElement>(`[data-step="${step}"]`)
    const invalid = fieldset?.querySelector<HTMLInputElement>(':invalid')
    invalid?.reportValidity()
    return !invalid
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!validateStep()) return
    if (!isLast) {
      setStep(step + 1)
      return
    }
    setStatus('loading')
    try {
      const data = Object.fromEntries(
        Array.from(new FormData(event.currentTarget), ([key, value]) => [key, String(value)]),
      )
      await onSubmit(data)
      setStatus('success')
    } catch {
      setStatus('error')
    }
  }

  if (status === 'success') {
    return (
      <div
        className={cn('rounded-3xl border bg-card p-10 text-center shadow-xl', className)}
        role="status"
      >
        <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-primary text-primary-foreground">
          <Check className="h-7 w-7" />
        </span>
        <h3 className="mt-5 text-2xl font-bold">{successTitle}</h3>
        <p className="mt-2 text-muted-foreground">{successDescription}</p>
      </div>
    )
  }

  return (
    <form
      ref={formRef}
      noValidate
      onSubmit={handleSubmit}
      className={cn('rounded-3xl border bg-card p-6 shadow-xl md:p-10', className)}
    >
      {title ? <h2 className="text-2xl font-bold tracking-tight md:text-3xl">{title}</h2> : null}

      <ol className="mt-6 flex items-center gap-2">
        {steps.map((item, index) => (
          <li key={item.title} className="flex flex-1 items-center gap-2">
            <span
              className={cn(
                'flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-sm font-bold transition',
                index <= step
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground',
              )}
              aria-current={index === step ? 'step' : undefined}
            >
              {index < step ? <Check className="h-4 w-4" /> : index + 1}
            </span>
            {index < steps.length - 1 ? (
              <span className="h-0.5 flex-1 overflow-hidden rounded bg-muted">
                <motion.span
                  className="block h-full bg-primary"
                  animate={{ width: index < step ? '100%' : '0%' }}
                  transition={{ duration: reduceMotion ? 0 : 0.4 }}
                />
              </span>
            ) : null}
          </li>
        ))}
      </ol>

      <div className="relative mt-8">
        {steps.map((item, index) => (
          <fieldset key={item.title} data-step={index} hidden={index !== step}>
            <legend className="text-lg font-semibold">
              {index + 1}. {item.title}
            </legend>
            <motion.div
              initial={false}
              animate={
                index === step ? { opacity: 1, x: 0 } : { opacity: 0, x: reduceMotion ? 0 : 24 }
              }
              transition={{ duration: reduceMotion ? 0 : 0.3 }}
              className="mt-5 grid gap-4 sm:grid-cols-2"
            >
              {item.fields.map((field) => (
                <label
                  key={field.name}
                  className={cn(
                    'grid gap-2 text-sm font-medium',
                    (field.fullWidth || field.type === 'textarea') && 'sm:col-span-2',
                  )}
                >
                  <span>
                    {field.label}
                    {field.required ? <span className="text-primary"> *</span> : null}
                  </span>
                  {field.type === 'textarea' ? (
                    <textarea
                      name={field.name}
                      required={field.required}
                      placeholder={field.placeholder}
                      rows={4}
                      className={fieldClass}
                    />
                  ) : field.type === 'select' ? (
                    <select
                      name={field.name}
                      required={field.required}
                      defaultValue=""
                      className={fieldClass}
                    >
                      <option value="" disabled>
                        {field.placeholder ?? 'Selecione'}
                      </option>
                      {field.options?.map((option) => (
                        <option key={option}>{option}</option>
                      ))}
                    </select>
                  ) : (
                    <input
                      name={field.name}
                      type={field.type ?? 'text'}
                      required={field.required}
                      placeholder={field.placeholder}
                      className={fieldClass}
                    />
                  )}
                </label>
              ))}
            </motion.div>
          </fieldset>
        ))}
      </div>

      {status === 'error' ? (
        <p className="mt-4 text-sm text-destructive" role="alert">
          {errorMessage}
        </p>
      ) : null}

      <div className="mt-8 flex justify-between gap-3">
        <button
          type="button"
          onClick={() => setStep(step - 1)}
          disabled={step === 0}
          className="rounded-full border px-6 py-3 text-sm font-semibold transition hover:border-primary hover:text-primary disabled:invisible"
        >
          {previousLabel}
        </button>
        <button
          type="submit"
          disabled={status === 'loading'}
          className="inline-flex items-center gap-2 rounded-full bg-primary px-6 py-3 text-sm font-semibold text-primary-foreground transition hover:bg-primary-hover disabled:opacity-60"
        >
          {status === 'loading' ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
          {isLast ? submitLabel : nextLabel}
        </button>
      </div>
    </form>
  )
}

import type { ReactNode } from 'react'
