'use client'

import { useEffect, useState, type ReactNode } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { ChevronDown, Clock, Mail, Menu, Phone, X } from 'lucide-react'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type NavbarAccentItem = {
  label: string
  href: string
  children?: readonly { label: string; href: string }[]
}

export type NavbarAccentProps = {
  logo: ReactNode
  items: readonly NavbarAccentItem[]
  logoHref?: string
  cta?: { label: string; href: string; icon?: ReactNode }
  topbar?: { phone?: string; phoneHref?: string; email?: string; hours?: string }
  socialLinks?: readonly { label: string; href: string; icon: ReactNode }[]
  position?: 'static' | 'sticky'
  tone?: AccentTone
  className?: string
}

const skins: Record<
  AccentTone,
  { bar: string; link: string; active: string; dropdown: string; drawer: string; burger: string }
> = {
  glow: {
    bar: 'bg-[#121212]/90 backdrop-blur',
    link: 'text-[#c1c1c1] hover:text-white',
    active: 'text-white',
    dropdown: 'rounded-b-md bg-[#221d2f]',
    drawer: 'bg-[#221d2f] text-white',
    burger: 'rounded-full border border-[#493849] text-white',
  },
  industrial: {
    bar: 'border-b border-slate-200 bg-white',
    link: 'text-slate-600 hover:text-slate-900',
    active: 'text-slate-900',
    dropdown: 'border border-slate-200 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.12)]',
    drawer: 'bg-white text-slate-900',
    burger: 'border border-slate-200 text-slate-800',
  },
  'industrial-dark': {
    bar: 'border-b border-white/10 bg-slate-950',
    link: 'text-slate-400 hover:text-white',
    active: 'text-white',
    dropdown: 'border border-white/10 bg-slate-900',
    drawer: 'bg-slate-950 text-white',
    burger: 'border border-white/20 text-white',
  },
}

/** Cabeçalho com dropdowns, CTA, topbar opcional de contatos e drawer mobile. */
export function NavbarAccent({
  logo,
  items,
  logoHref = '/',
  cta,
  topbar,
  socialLinks = [],
  position = 'sticky',
  tone = 'industrial',
  className,
}: NavbarAccentProps) {
  const t = getAccentTone(tone)
  const skin = skins[tone]
  const pathname = usePathname()
  const [open, setOpen] = useState(false)
  const [expanded, setExpanded] = useState<string | null>(null)

  const close = (): void => {
    setOpen(false)
    setExpanded(null)
  }

  useEffect(() => {
    close()
  }, [pathname])

  useEffect(() => {
    if (!open) return
    const previous = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') close()
    }
    window.addEventListener('keydown', onKey)
    return () => {
      document.body.style.overflow = previous
      window.removeEventListener('keydown', onKey)
    }
  }, [open])

  const isActive = (href: string): boolean =>
    href === '/' ? pathname === '/' : pathname === href || pathname.startsWith(`${href}/`)

  const underline = (active: boolean): string =>
    cn(
      'absolute -bottom-1 left-0 h-0.5 transition-all duration-300',
      t.line,
      active ? 'w-full' : 'w-0 group-hover:w-full',
    )

  const contacts = topbar
    ? ([
        topbar.phone && {
          icon: <Phone className="h-3.5 w-3.5" />,
          label: topbar.phone,
          href: `tel:${topbar.phoneHref ?? topbar.phone}`,
        },
        topbar.email && {
          icon: <Mail className="h-3.5 w-3.5" />,
          label: topbar.email,
          href: `mailto:${topbar.email}`,
        },
        topbar.hours && { icon: <Clock className="h-3.5 w-3.5" />, label: topbar.hours },
      ].filter(Boolean) as { icon: ReactNode; label: string; href?: string }[])
    : []

  return (
    <>
      {contacts.length ? (
        <div
          className={cn(
            'hidden text-sm lg:block',
            tone === 'glow'
              ? 'border-b border-[#493849] bg-[#0e0e0e] text-[#c1c1c1]'
              : 'border-b border-slate-800 bg-slate-900 text-slate-300',
          )}
        >
          <div className="container flex h-10 items-center gap-6">
            {contacts.map((contact) => {
              const body = (
                <>
                  <span
                    className={tone === 'glow' ? 'text-[#ffb0eb]' : 'text-amber-500'}
                    aria-hidden
                  >
                    {contact.icon}
                  </span>
                  {contact.label}
                </>
              )
              return contact.href ? (
                <a
                  key={contact.label}
                  href={contact.href}
                  className="inline-flex items-center gap-2 transition-colors hover:text-white"
                >
                  {body}
                </a>
              ) : (
                <span key={contact.label} className="ml-auto inline-flex items-center gap-2">
                  {body}
                </span>
              )
            })}
          </div>
        </div>
      ) : null}

      <header
        className={cn('z-50 w-full', position === 'sticky' && 'sticky top-0', skin.bar, className)}
      >
        <div className="container grid min-h-[4.5rem] grid-cols-[1fr_auto] items-center gap-4 py-3 lg:min-h-20 lg:grid-cols-[1fr_auto_1fr] lg:py-0">
          <Link href={logoHref} className={cn('flex items-center justify-self-start', t.focus)}>
            {logo}
          </Link>

          <nav className="hidden items-center gap-1 lg:flex" aria-label="Principal">
            {items.map((item) =>
              item.children?.length ? (
                <div key={item.label} className="group relative">
                  <Link
                    href={item.href}
                    className={cn(
                      'inline-flex items-center gap-1.5 px-3.5 py-2 text-[0.9375rem] font-medium tracking-wide transition-colors',
                      isActive(item.href) ? skin.active : skin.link,
                      t.focus,
                    )}
                  >
                    <span className="relative">
                      {item.label}
                      <span className={underline(isActive(item.href))} />
                    </span>
                    <ChevronDown className="h-3.5 w-3.5 transition-transform duration-200 group-focus-within:rotate-180 group-hover:rotate-180" />
                  </Link>
                  <div className="invisible absolute left-0 top-full z-50 min-w-[220px] translate-y-1 pt-2 opacity-0 transition-all duration-200 group-focus-within:visible group-focus-within:translate-y-0 group-focus-within:opacity-100 group-hover:visible group-hover:translate-y-0 group-hover:opacity-100">
                    <ul className={cn('overflow-hidden', skin.dropdown)}>
                      <li className={cn('h-0.5 w-full', t.line)} aria-hidden />
                      {item.children.map((child) => (
                        <li key={child.label} className={cn('border-b last:border-b-0', t.border)}>
                          <Link
                            href={child.href}
                            className={cn(
                              'block whitespace-nowrap px-4 py-3 text-sm font-medium transition-colors',
                              skin.link,
                              t.panelHover,
                              t.focus,
                            )}
                          >
                            {child.label}
                          </Link>
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ) : (
                <Link
                  key={item.label}
                  href={item.href}
                  aria-current={isActive(item.href) ? 'page' : undefined}
                  className={cn(
                    'group relative px-3.5 py-2 text-[0.9375rem] font-medium tracking-wide transition-colors',
                    isActive(item.href) ? skin.active : skin.link,
                    t.focus,
                  )}
                >
                  <span className="relative">
                    {item.label}
                    <span className={underline(isActive(item.href))} />
                  </span>
                </Link>
              ),
            )}
          </nav>

          <div className="flex items-center justify-end gap-3">
            {cta ? (
              <div className="hidden lg:block">
                <AccentButton tone={tone} href={cta.href} icon={cta.icon}>
                  {cta.label}
                </AccentButton>
              </div>
            ) : null}
            <button
              type="button"
              onClick={() => setOpen(true)}
              className={cn(
                'inline-flex h-10 w-10 items-center justify-center lg:hidden',
                skin.burger,
                t.focus,
              )}
              aria-expanded={open}
              aria-controls="navbar-accent-drawer"
              aria-label="Abrir menu"
            >
              <Menu className="h-5 w-5" />
            </button>
          </div>
        </div>
      </header>

      <div
        className={cn(
          'fixed inset-0 z-[55] bg-black/60 backdrop-blur-[2px] transition-opacity duration-300 lg:hidden',
          open ? 'opacity-100' : 'pointer-events-none opacity-0',
        )}
        onClick={close}
        aria-hidden
      />

      <aside
        id="navbar-accent-drawer"
        role="dialog"
        aria-modal="true"
        aria-label="Menu"
        className={cn(
          'fixed inset-y-0 right-0 z-[60] flex w-[min(100%,22rem)] flex-col shadow-2xl transition-[transform,visibility] duration-300 ease-out lg:hidden',
          skin.drawer,
          open ? 'visible translate-x-0' : 'invisible translate-x-full',
        )}
      >
        <div className={cn('flex h-[4.5rem] items-center justify-between border-b px-5', t.border)}>
          <Link href={logoHref} onClick={close} className={t.focus}>
            {logo}
          </Link>
          <button
            type="button"
            onClick={close}
            className={cn(
              'inline-flex h-10 w-10 items-center justify-center',
              skin.burger,
              t.focus,
            )}
            aria-label="Fechar menu"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto px-5 py-6" aria-label="Mobile">
          <ul>
            {items.map((item) => (
              <li key={item.label} className={cn('border-b', t.border)}>
                <div className="flex items-center">
                  <Link
                    href={item.href}
                    onClick={close}
                    className={cn(
                      'flex-1 py-3.5 font-medium tracking-wide',
                      isActive(item.href) ? skin.active : skin.link,
                    )}
                  >
                    {item.label}
                  </Link>
                  {item.children?.length ? (
                    <button
                      type="button"
                      onClick={() => setExpanded(expanded === item.label ? null : item.label)}
                      className={cn(
                        'inline-flex h-10 w-10 items-center justify-center',
                        t.accent,
                        t.focus,
                      )}
                      aria-expanded={expanded === item.label}
                      aria-label={`Expandir ${item.label}`}
                    >
                      <ChevronDown
                        className={cn(
                          'h-4 w-4 transition-transform',
                          expanded === item.label && 'rotate-180',
                        )}
                      />
                    </button>
                  ) : null}
                </div>
                {item.children?.length && expanded === item.label ? (
                  <ul
                    className={cn(
                      'mb-3 space-y-1 border-l-2 pl-4',
                      tone === 'glow' ? 'border-[#c642a5]' : 'border-amber-500',
                    )}
                  >
                    {item.children.map((child) => (
                      <li key={child.label}>
                        <Link
                          href={child.href}
                          onClick={close}
                          className={cn('block py-2 text-sm', skin.link)}
                        >
                          {child.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </li>
            ))}
          </ul>
        </nav>

        {socialLinks.length || contacts.length || cta ? (
          <div className={cn('space-y-4 border-t p-5', t.border, t.alt)}>
            {socialLinks.length ? (
              <div className="flex items-center gap-3">
                {socialLinks.map((social) => (
                  <a
                    key={social.label}
                    href={social.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    aria-label={social.label}
                    className={cn(
                      'inline-flex h-10 w-10 items-center justify-center',
                      t.iconButton,
                      t.focus,
                    )}
                  >
                    {social.icon}
                  </a>
                ))}
              </div>
            ) : null}
            {contacts.length ? (
              <div className={cn('space-y-2.5 text-sm', t.body)}>
                {contacts.map((contact) => (
                  <p key={contact.label} className="flex items-center gap-2.5">
                    <span className={t.accent} aria-hidden>
                      {contact.icon}
                    </span>
                    {contact.href ? <a href={contact.href}>{contact.label}</a> : contact.label}
                  </p>
                ))}
              </div>
            ) : null}
            {cta ? (
              <AccentButton tone={tone} href={cta.href} icon={cta.icon} onClick={close}>
                {cta.label}
              </AccentButton>
            ) : null}
          </div>
        ) : null}
      </aside>
    </>
  )
}

import type { MouseEventHandler, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

import type { AccentTone } from './accentTones'

export type AccentButtonProps = {
  children: ReactNode
  href?: string
  tone?: AccentTone
  size?: 'md' | 'lg'
  icon?: ReactNode
  external?: boolean
  type?: 'button' | 'submit'
  disabled?: boolean
  onClick?: MouseEventHandler<HTMLElement>
  className?: string
}

const slideBase =
  'group relative inline-flex w-fit cursor-pointer items-center overflow-hidden rounded-sm font-semibold tracking-wide transition-all duration-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60'

const slideSizes = {
  md: {
    root: 'h-12 p-1.5 ps-5 pe-14 text-sm hover:ps-14 hover:pe-5',
    icon: 'right-1.5 h-9 w-9 group-hover:right-[calc(100%-42px)]',
  },
  lg: {
    root: 'h-14 p-1 ps-6 pe-20 text-base hover:ps-20 hover:pe-6 md:text-lg',
    icon: 'right-1.5 h-11 w-11 group-hover:right-[calc(100%-50px)]',
  },
}

const toneClasses: Record<AccentTone, { root: string; icon: string }> = {
  glow: {
    root: 'inline-flex items-center justify-center gap-2 rounded-full border-2 border-[#7c39cf] bg-transparent px-4 py-2 font-semibold text-[#ae89ff] transition-[color,border-color,box-shadow,background-color] duration-300 hover:border-[#c642a5] hover:bg-gradient-to-r hover:from-[#86196b] hover:to-[#5327b3] hover:text-white hover:shadow-[0_0_8px_#c642a5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#c642a5] focus-visible:ring-offset-2 focus-visible:ring-offset-[#121212] disabled:pointer-events-none disabled:opacity-60',
    icon: '',
  },
  industrial: {
    root: 'bg-slate-900 text-white hover:bg-amber-500 hover:text-slate-950',
    icon: 'bg-white text-slate-900 group-hover:bg-slate-950 group-hover:text-white',
  },
  'industrial-dark': {
    root: 'bg-amber-500 text-slate-950 hover:bg-white',
    icon: 'bg-white text-slate-950 group-hover:bg-slate-950 group-hover:text-white',
  },
}

/** Botão de ação dos templates: contorno com gradiente (glow) ou ícone deslizante (industrial). */
export function AccentButton({
  children,
  href,
  tone = 'glow',
  size = 'md',
  icon,
  external,
  type = 'button',
  disabled,
  onClick,
  className,
}: AccentButtonProps) {
  const styles = toneClasses[tone]
  const isGlow = tone === 'glow'
  const resolvedIcon = icon ?? <ArrowUpRight className="h-4 w-4 shrink-0" aria-hidden />
  const classes = isGlow
    ? cn(styles.root, size === 'lg' && 'px-6 py-3 text-lg', className)
    : cn(slideBase, slideSizes[size].root, styles.root, className)

  const content = isGlow ? (
    <>
      {icon}
      {children}
    </>
  ) : (
    <>
      <span className="relative z-10 transition-colors duration-500">{children}</span>
      <span
        className={cn(
          'absolute flex items-center justify-center rounded-full transition-all duration-500 group-hover:rotate-12',
          slideSizes[size].icon,
          styles.icon,
        )}
        aria-hidden
      >
        {resolvedIcon}
      </span>
    </>
  )

  if (href) {
    const isExternal = external ?? /^(https?:|mailto:|tel:)/.test(href)
    if (isExternal) {
      return (
        <a
          href={href}
          className={classes}
          onClick={onClick}
          target={href.startsWith('http') ? '_blank' : undefined}
          rel={href.startsWith('http') ? 'noopener noreferrer' : undefined}
        >
          {content}
        </a>
      )
    }
    return (
      <Link href={href} className={classes} onClick={onClick}>
        {content}
      </Link>
    )
  }

  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  )
}

'use client'

import { useSyncExternalStore } from 'react'

const subscribe = () => () => {}

/**
 * Ano atual lido só no navegador: não chama `new Date()` no prerender,
 * o que o Next 16 com `cacheComponents` rejeita.
 */
export function CurrentYear() {
  return useSyncExternalStore(
    subscribe,
    () => new Date().getFullYear(),
    () => null,
  )
}

import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

import { getAccentTone, type AccentTone } from './accentTones'

export type EyebrowHeadingProps = {
  title: ReactNode
  eyebrow?: ReactNode
  description?: ReactNode
  tone?: AccentTone
  align?: 'left' | 'center'
  layout?: 'stacked' | 'split'
  size?: 'md' | 'lg'
  titleAs?: 'h1' | 'h2' | 'h3'
  action?: ReactNode
  className?: string
}

const titleSizes = {
  md: 'text-3xl leading-[1.15] sm:text-4xl lg:text-[2.5rem]',
  lg: 'text-3xl leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
}

/** Cabeçalho de seção com linha de destaque, título temático e descrição opcional ao lado. */
export function EyebrowHeading({
  title,
  eyebrow,
  description,
  tone = 'glow',
  align = 'left',
  layout = 'stacked',
  size = 'md',
  titleAs: Title = 'h2',
  action,
  className,
}: EyebrowHeadingProps) {
  const t = getAccentTone(tone)
  const centered = align === 'center'
  const split = layout === 'split' && !centered

  const line = <span className={cn('h-px w-8 shrink-0', t.line)} aria-hidden />

  return (
    <div
      className={cn(
        split && 'flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between',
        centered && 'mx-auto max-w-3xl text-center',
        className,
      )}
    >
      <div className={cn(split ? 'max-w-2xl' : centered ? '' : 'max-w-3xl')}>
        {eyebrow ? (
          <div className={cn('mb-4 flex items-center gap-3', centered && 'justify-center')}>
            {line}
            <span
              className={cn('text-[0.65rem] font-medium uppercase tracking-[0.28em]', t.accent)}
            >
              {eyebrow}
            </span>
            {centered ? line : null}
          </div>
        ) : null}
        <Title className={cn(t.heading, titleSizes[size], centered && 'mx-auto')}>{title}</Title>
        {!split && description ? (
          <p
            className={cn(
              'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
              t.body,
              centered && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
        {!split && action ? (
          <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
            {action}
          </div>
        ) : null}
      </div>
      {split && (description || action) ? (
        <div className="max-w-md space-y-5">
          {description ? (
            <p className={cn('text-sm leading-relaxed lg:text-base', t.body)}>{description}</p>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  )
}

import type { ButtonHTMLAttributes, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'

import { Button, type ButtonProps } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HoverButtonEffect = 'lift' | 'shine' | 'slide' | 'glow' | 'underline' | 'expand-icon'

export interface HoverButtonProps extends Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  'children'
> {
  children: ReactNode
  href?: string
  effect?: HoverButtonEffect
  variant?: ButtonProps['variant']
  size?: ButtonProps['size']
  icon?: ReactNode
  iconPosition?: 'left' | 'right'
}

const effectClasses: Record<HoverButtonEffect, string> = {
  lift: 'transition-all duration-300 hover:-translate-y-1 hover:shadow-lg active:translate-y-0',
  shine:
    'relative overflow-hidden before:absolute before:inset-y-0 before:-left-1/2 before:w-1/3 before:-skew-x-12 before:bg-white/30 before:blur-sm before:transition-all before:duration-500 hover:before:left-[120%]',
  slide:
    'relative overflow-hidden border-primary bg-transparent text-primary before:absolute before:inset-0 before:-translate-x-full before:bg-primary before:transition-transform before:duration-300 hover:text-primary-foreground hover:before:translate-x-0',
  glow: 'transition-all duration-300 hover:shadow-[0_0_28px_hsl(var(--primary)/0.45)]',
  underline:
    'relative rounded-none bg-transparent text-foreground after:absolute after:bottom-1 after:left-1/2 after:h-0.5 after:w-0 after:bg-primary after:transition-all after:duration-300 hover:bg-transparent hover:after:left-0 hover:after:w-full',
  'expand-icon': 'group transition-all duration-300 hover:pr-6',
}

export function HoverButton({
  children,
  href,
  effect = 'lift',
  variant = 'default',
  size = 'default',
  icon,
  iconPosition = 'right',
  className,
  type = 'button',
  ...props
}: HoverButtonProps) {
  const trailingIcon =
    effect === 'expand-icon' && !icon ? <ArrowRight className="h-4 w-4" aria-hidden /> : icon

  const content = (
    <>
      {iconPosition === 'left' ? trailingIcon : null}
      <span className="relative z-10">{children}</span>
      {iconPosition === 'right' ? trailingIcon : null}
    </>
  )

  const classes = cn(
    'gap-2',
    effectClasses[effect],
    effect === 'expand-icon' &&
      '[&_svg]:transition-transform [&_svg]:duration-300 hover:[&_svg]:translate-x-1',
    className,
  )

  if (href) {
    return (
      <Button asChild variant={variant} size={size} className={classes}>
        <Link href={href}>{content}</Link>
      </Button>
    )
  }

  return (
    <Button type={type} variant={variant} size={size} className={classes} {...props}>
      {content}
    </Button>
  )
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline:
          'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-8',
        icon: 'h-9 w-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    )
  },
)
Button.displayName = 'Button'

export { Button, buttonVariants }

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
